[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CreativeHub — Online Classes for Creatives</title>
  <meta name="description" content="An online learning community offering thousands of creative classes taught by industry professionals, from illustration and design to photography and filmmaking.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --font-heading: 'Plus Jakarta Sans', sans-serif;
      --font-body: 'Inter', sans-serif;
      --black: #0F0F14;
      --charcoal: #1A1A2E;
      --dark-surface: #22223A;
      --navy: #16213E;
      --white: #FFFFFF;
      --off-white: #F7F7FB;
      --gray-50: #FAFAFC;
      --gray-100: #F0F0F5;
      --gray-200: #E2E2EA;
      --gray-300: #C4C4D0;
      --gray-400: #9494A8;
      --gray-500: #6E6E82;
      --gray-600: #4A4A5E;
      --coral: #FF6B4A;
      --coral-light: #FF8A6E;
      --green: #55DA9B;
      --green-dark: #3CC484;
      --purple: #5620C1;
      --purple-light: #7B4FDB;
      --yellow: #FFD84D;
      --yellow-dark: #F5C518;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-pill: 9999px;
      --shadow-sm: 0 1px 3px rgba(15,15,20,0.06);
      --shadow-md: 0 4px 16px rgba(15,15,20,0.08);
      --shadow-lg: 0 8px 32px rgba(15,15,20,0.12);
      --shadow-xl: 0 16px 48px rgba(15,15,20,0.16);
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 400ms ease;
      --max-width: 1200px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--black);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: var(--font-heading);
      font-weight: 800;
      line-height: 1.15;
    }

    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; font-family: var(--font-body); }
    img { max-width: 100%; display: block; }
    ul { list-style: none; }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    @media (min-width: 768px) {
      .container { padding: 0 40px; }
    }

    /* ============================================
       HEADER / NAVIGATION
    ============================================ */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(26, 26, 46, 0.95);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
      transition: background var(--transition-base);
    }

    .header-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    @media (min-width: 768px) {
      .header-inner { padding: 0 40px; height: 72px; }
    }

    .logo {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 22px;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 32px;
      height: 32px;
      background: var(--green);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 18px;
      height: 18px;
    }

    .nav-links {
      display: none;
      align-items: center;
      gap: 32px;
    }

    @media (min-width: 768px) {
      .nav-links { display: flex; }
    }

    .nav-links a {
      color: rgba(255,255,255,0.7);
      font-size: 14px;
      font-weight: 500;
      transition: color var(--transition-fast);
    }

    .nav-links a:hover, .nav-links a:focus-visible {
      color: var(--white);
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-sign-in {
      background: transparent;
      color: rgba(255,255,255,0.8);
      font-size: 14px;
      font-weight: 500;
      padding: 8px 16px;
      border-radius: var(--radius-pill);
      transition: color var(--transition-fast);
      display: none;
    }

    @media (min-width: 768px) {
      .btn-sign-in { display: inline-flex; }
    }

    .btn-sign-in:hover { color: var(--white); }

    .btn-signup-header {
      background: var(--green);
      color: var(--black);
      font-size: 14px;
      font-weight: 600;
      padding: 10px 20px;
      border-radius: var(--radius-pill);
      transition: background var(--transition-fast), transform var(--transition-fast);
    }

    .btn-signup-header:hover {
      background: var(--green-dark);
      transform: translateY(-1px);
    }

    .mobile-menu-btn {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 40px;
      height: 40px;
      background: transparent;
      color: var(--white);
      border-radius: var(--radius-sm);
    }

    @media (min-width: 768px) {
      .mobile-menu-btn { display: none; }
    }

    .mobile-menu-btn svg { width: 24px; height: 24px; }

    /* ============================================
       HERO SECTION
    ============================================ */
    .hero {
      background: linear-gradient(170deg, var(--charcoal) 0%, var(--black) 60%, #0D0D18 100%);
      padding: 120px 0 72px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(86,32,193,0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(85,218,155,0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      text-align: center;
      max-width: 720px;
      margin: 0 auto;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85,218,155,0.12);
      border: 1px solid rgba(85,218,155,0.2);
      color: var(--green);
      font-size: 13px;
      font-weight: 600;
      padding: 6px 16px;
      border-radius: var(--radius-pill);
      margin-bottom: 24px;
    }

    .hero-badge svg { width: 14px; height: 14px; }

    .hero h1 {
      color: var(--white);
      font-size: clamp(32px, 6vw, 56px);
      letter-spacing: -0.03em;
      margin-bottom: 16px;
    }

    .hero h1 .accent-green { color: var(--green); }
    .hero h1 .accent-coral { color: var(--coral); }

    .hero-subtitle {
      color: rgba(255,255,255,0.65);
      font-size: clamp(16px, 2.5vw, 20px);
      margin-bottom: 36px;
      font-weight: 400;
    }

    .hero-subtitle strong {
      color: var(--yellow);
      font-weight: 600;
    }

    .hero-ctas {
      display: flex;
      flex-direction: column;
      gap: 12px;
      max-width: 380px;
      margin: 0 auto 20px;
    }

    @media (min-width: 480px) {
      .hero-ctas {
        flex-direction: row;
        max-width: 460px;
      }
    }

    .btn-hero {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 14px 28px;
      font-size: 15px;
      font-weight: 600;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
      flex: 1;
      min-height: 52px;
    }

    .btn-hero svg { width: 20px; height: 20px; flex-shrink: 0; }

    .btn-google {
      background: var(--white);
      color: var(--black);
    }

    .btn-google:hover {
      background: var(--gray-100);
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(255,255,255,0.15);
    }

    .btn-email {
      background: var(--green);
      color: var(--black);
    }

    .btn-email:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(85,218,155,0.3);
    }

    .hero-legal {
      color: rgba(255,255,255,0.35);
      font-size: 11px;
      line-height: 1.5;
      max-width: 440px;
      margin: 0 auto 48px;
    }

    .hero-legal a {
      color: rgba(255,255,255,0.5);
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    .hero-legal a:hover { color: rgba(255,255,255,0.7); }

    .category-pills {
      display: flex;
      gap: 10px;
      overflow-x: auto;
      padding: 0 24px 8px;
      margin: 0 -24px;
      scrollbar-width: none;
      -ms-overflow-style: none;
      justify-content: flex-start;
    }

    .category-pills::-webkit-scrollbar { display: none; }

    @media (min-width: 900px) {
      .category-pills {
        flex-wrap: wrap;
        justify-content: center;
        overflow-x: visible;
        padding: 0;
        margin: 0;
      }
    }

    .category-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;
      padding: 10px 20px;
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      color: rgba(255,255,255,0.75);
      font-size: 14px;
      font-weight: 500;
      border-radius: var(--radius-pill);
      transition: all var(--transition-fast);
      flex-shrink: 0;
    }

    .category-pill:hover {
      background: rgba(255,255,255,0.12);
      border-color: rgba(255,255,255,0.2);
      color: var(--white);
      transform: translateY(-1px);
    }

    .category-pill svg { width: 16px; height: 16px; opacity: 0.7; }

    /* ============================================
       FEATURES / VALUE PROPOSITIONS
    ============================================ */
    .features {
      padding: 96px 0;
      background: var(--white);
    }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--purple);
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      margin-bottom: 12px;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 42px);
      letter-spacing: -0.02em;
      margin-bottom: 16px;
      color: var(--black);
    }

    .section-subtitle {
      color: var(--gray-500);
      font-size: 17px;
      max-width: 560px;
      line-height: 1.7;
    }

    .features-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .features-header .section-subtitle {
      margin: 0 auto;
    }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }

    @media (min-width: 640px) {
      .features-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (min-width: 1024px) {
      .features-grid { grid-template-columns: repeat(4, 1fr); }
    }

    .feature-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px 24px;
      text-align: center;
      transition: all var(--transition-base);
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
      border-color: transparent;
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
    }

    .feature-icon svg { width: 28px; height: 28px; }

    .feature-icon--green { background: rgba(85,218,155,0.12); color: var(--green-dark); }
    .feature-icon--coral { background: rgba(255,107,74,0.12); color: var(--coral); }
    .feature-icon--purple { background: rgba(86,32,193,0.1); color: var(--purple); }
    .feature-icon--yellow { background: rgba(255,216,77,0.15); color: var(--yellow-dark); }

    .feature-card h3 {
      font-size: 17px;
      font-weight: 700;
      margin-bottom: 8px;
      color: var(--black);
    }

    .feature-card p {
      color: var(--gray-500);
      font-size: 14px;
      line-height: 1.6;
    }

    /* ============================================
       STATS SECTION
    ============================================ */
    .stats {
      background: linear-gradient(135deg, var(--charcoal) 0%, var(--navy) 100%);
      padding: 72px 0;
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      top: 0;
      left: 50%;
      transform: translateX(-50%);
      width: 800px;
      height: 200px;
      background: radial-gradient(ellipse, rgba(85,218,155,0.08), transparent 70%);
      pointer-events: none;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 32px;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    @media (min-width: 768px) {
      .stats-grid { grid-template-columns: repeat(4, 1fr); }
    }

    .stat-item {
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .stat-number {
      font-family: var(--font-heading);
      font-size: clamp(36px, 5vw, 52px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-number--green { color: var(--green); }
    .stat-number--coral { color: var(--coral); }
    .stat-number--yellow { color: var(--yellow); }
    .stat-number--purple { color: var(--purple-light); }

    .stat-label {
      color: rgba(255,255,255,0.6);
      font-size: 14px;
      font-weight: 500;
    }

    .stat-star {
      color: var(--yellow);
      margin-left: 2px;
    }

    /* ============================================
       COURSES SECTION
    ============================================ */
    .courses {
      padding: 96px 0;
      background: var(--off-white);
    }

    .courses-header {
      text-align: center;
      margin-bottom: 40px;
    }

    .course-tabs {
      display: flex;
      gap: 6px;
      overflow-x: auto;
      padding-bottom: 8px;
      margin-bottom: 40px;
      scrollbar-width: none;
      -ms-overflow-style: none;
    }

    .course-tabs::-webkit-scrollbar { display: none; }

    .course-tab {
      white-space: nowrap;
      padding: 10px 20px;
      background: transparent;
      border: 1px solid var(--gray-200);
      color: var(--gray-500);
      font-size: 14px;
      font-weight: 500;
      border-radius: var(--radius-pill);
      transition: all var(--transition-fast);
      flex-shrink: 0;
    }

    .course-tab:hover {
      border-color: var(--gray-300);
      color: var(--black);
    }

    .course-tab.active {
      background: var(--black);
      border-color: var(--black);
      color: var(--white);
    }

    .course-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }

    @media (min-width: 640px) {
      .course-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (min-width: 1024px) {
      .course-grid { grid-template-columns: repeat(4, 1fr); }
    }

    .course-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition-base);
      border: 1px solid var(--gray-200);
    }

    .course-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
      border-color: transparent;
    }

    .course-thumb {
      position: relative;
      aspect-ratio: 16 / 10;
      overflow: hidden;
    }

    .course-thumb-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      font-weight: 800;
      font-family: var(--font-heading);
      color: var(--white);
    }

    .course-thumb-bg svg { width: 48px; height: 48px; opacity: 0.7; }

    .course-duration-badge {
      position: absolute;
      bottom: 8px;
      right: 8px;
      background: rgba(0,0,0,0.75);
      color: var(--white);
      font-size: 12px;
      font-weight: 600;
      padding: 4px 10px;
      border-radius: var(--radius-sm);
      backdrop-filter: blur(4px);
    }

    .course-info { padding: 16px; }

    .course-info h3 {
      font-size: 14px;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 10px;
      color: var(--black);
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }

    .course-instructor {
      font-size: 13px;
      color: var(--gray-500);
      font-weight: 500;
    }

    .course-students {
      font-size: 12px;
      color: var(--gray-400);
      display: flex;
      align-items: center;
      gap: 4px;
      white-space: nowrap;
    }

    .course-students svg { width: 14px; height: 14px; }

    /* ============================================
       CREATIVE FEED
    ============================================ */
    .creative-feed {
      padding: 96px 0;
      background: var(--white);
    }

    .creative-feed-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .feed-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }

    @media (min-width: 768px) {
      .feed-grid { grid-template-columns: repeat(3, 1fr); }
    }

    .feed-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 36px 28px;
      transition: all var(--transition-base);
      position: relative;
      overflow: hidden;
    }

    .feed-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
    }

    .feed-card--inspired::before { background: var(--coral); }
    .feed-card--connected::before { background: var(--green); }
    .feed-card--creating::before { background: var(--purple); }

    .feed-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .feed-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .feed-icon svg { width: 24px; height: 24px; }

    .feed-icon--coral { background: rgba(255,107,74,0.12); color: var(--coral); }
    .feed-icon--green { background: rgba(85,218,155,0.12); color: var(--green-dark); }
    .feed-icon--purple { background: rgba(86,32,193,0.1); color: var(--purple); }

    .feed-card h3 {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 10px;
      color: var(--black);
    }

    .feed-card p {
      color: var(--gray-500);
      font-size: 15px;
      line-height: 1.65;
    }

    /* ============================================
       TEACHERS SECTION
    ============================================ */
    .teachers {
      padding: 96px 0;
      background: var(--off-white);
    }

    .teachers-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .teachers-header .section-subtitle {
      margin: 0 auto;
      max-width: 640px;
    }

    .teachers-carousel-wrapper {
      position: relative;
    }

    .teachers-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding-bottom: 8px;
    }

    .teachers-carousel::-webkit-scrollbar { display: none; }

    .teacher-card {
      flex: 0 0 260px;
      scroll-snap-align: start;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition-base);
    }

    .teacher-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
      border-color: transparent;
    }

    .teacher-avatar {
      width: 100%;
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 48px;
      color: var(--white);
    }

    .teacher-info {
      padding: 20px;
      text-align: center;
    }

    .teacher-info h3 {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 4px;
      color: var(--black);
    }

    .teacher-info p {
      font-size: 13px;
      color: var(--gray-500);
      font-weight: 500;
    }

    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
      color: var(--black);
    }

    .carousel-btn:hover {
      background: var(--black);
      color: var(--white);
      border-color: var(--black);
    }

    .carousel-btn svg { width: 20px; height: 20px; }

    /* ============================================
       TESTIMONIALS
    ============================================ */
    .testimonials {
      padding: 96px 0;
      background: var(--white);
    }

    .testimonials-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }

    @media (min-width: 640px) {
      .testimonials-grid { grid-template-columns: repeat(2, 1fr); }
    }

    .testimonial-card {
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      transition: all var(--transition-base);
    }

    .testimonial-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 16px;
      color: var(--yellow);
    }

    .testimonial-stars svg { width: 16px; height: 16px; }

    .testimonial-card blockquote {
      font-size: 15px;
      line-height: 1.7;
      color: var(--gray-600);
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: 16px;
      color: var(--white);
    }

    .testimonial-name {
      font-size: 14px;
      font-weight: 600;
      color: var(--black);
    }

    /* ============================================
       TEAMS SECTION
    ============================================ */
    .teams {
      padding: 96px 0;
      background: linear-gradient(135deg, var(--charcoal) 0%, #1E1E36 100%);
      position: relative;
      overflow: hidden;
    }

    .teams::before {
      content: '';
      position: absolute;
      right: -200px;
      top: -100px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(86,32,193,0.12), transparent 70%);
      pointer-events: none;
    }

    .teams-content {
      position: relative;
      z-index: 1;
      max-width: 600px;
      margin: 0 auto;
      text-align: center;
    }

    .teams-content .section-label { color: var(--green); }

    .teams-content .section-title { color: var(--white); }

    .teams-content p {
      color: rgba(255,255,255,0.6);
      font-size: 16px;
      line-height: 1.7;
      margin-bottom: 32px;
    }

    .btn-teams {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--green);
      color: var(--black);
      font-size: 15px;
      font-weight: 600;
      padding: 14px 32px;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
    }

    .btn-teams:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(85,218,155,0.3);
    }

    .btn-teams svg { width: 18px; height: 18px; }

    /* ============================================
       FAQ SECTION
    ============================================ */
    .faq {
      padding: 96px 0;
      background: var(--white);
    }

    .faq-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .faq-list {
      max-width: 720px;
      margin: 0 auto;
    }

    .faq-item {
      border-bottom: 1px solid var(--gray-200);
    }

    .faq-item:first-child { border-top: 1px solid var(--gray-200); }

    .faq-question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 20px 0;
      background: transparent;
      font-size: 16px;
      font-weight: 600;
      color: var(--black);
      text-align: left;
      transition: color var(--transition-fast);
      font-family: var(--font-heading);
    }

    .faq-question:hover { color: var(--purple); }

    .faq-question:focus-visible {
      outline: 2px solid var(--purple);
      outline-offset: 2px;
      border-radius: 4px;
    }

    .faq-icon {
      width: 28px;
      height: 28px;
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      background: var(--gray-100);
      transition: all var(--transition-base);
    }

    .faq-icon svg {
      width: 16px;
      height: 16px;
      transition: transform var(--transition-base);
    }

    .faq-item.active .faq-icon {
      background: var(--purple);
      color: var(--white);
    }

    .faq-item.active .faq-icon svg {
      transform: rotate(45deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-slow);
    }

    .faq-answer-inner {
      padding: 0 0 20px;
      color: var(--gray-500);
      font-size: 15px;
      line-height: 1.7;
    }

    /* ============================================
       FOOTER
    ============================================ */
    .footer {
      background: var(--black);
      padding: 64px 0 32px;
      color: rgba(255,255,255,0.6);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    @media (min-width: 640px) {
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (min-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(5, 1fr); }
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .footer-col a {
      display: block;
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      padding: 4px 0;
      transition: color var(--transition-fast);
    }

    .footer-col a:hover { color: var(--green); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.08);
      padding-top: 24px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      align-items: center;
      text-align: center;
    }

    @media (min-width: 768px) {
      .footer-bottom {
        flex-direction: row;
        justify-content: space-between;
        text-align: left;
      }
    }

    .footer-bottom p {
      font-size: 12px;
      color: rgba(255,255,255,0.35);
      max-width: 600px;
      line-height: 1.6;
    }

    .footer-logo {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 18px;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .footer-logo .logo-icon {
      width: 28px;
      height: 28px;
    }

    .footer-logo .logo-icon svg { width: 16px; height: 16px; }

    /* ============================================
       UTILITIES / ANIMATIONS
    ============================================ */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      white-space: nowrap;
      border-width: 0;
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
      html { scroll-behavior: auto; }
    }

    .fade-in {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity 0.6s ease, transform 0.6s ease;
    }

    .fade-in.visible {
      opacity: 1;
      transform: translateY(0);
    }

    :focus-visible {
      outline: 2px solid var(--purple);
      outline-offset: 2px;
    }
  </style>
</head>
